/* tests/abi_test.c: the C ABI (include/vbm_sse.h) against the shared vectors (vbm-sse-vectors-1, generated by the Lean REFERENCE). Hosted test code, not shipped. Every row is run on every cut the runners
 * of the bindings use: the whole input as one chunk, one byte per chunk, and each two-way split (including an empty first or second chunk); the events collected from the reports, the final last event ID and
 * the reconnection time must equal the row's. Then the argument checks, a report that survives until the next call, and the leak hook (the runtime's live bytes are flat over many streams).
 * Usage: abi_test VECTORS.jsonl. Exit 0 = all correct. */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "../include/vbm_sse.h"
size_t vbm_sse_rt_live(void);   /* the runtime's test hook (kept global by scripts/build_native.sh through VBM_KEEP) */
static int bad;
#define CHECK(c, what) do { if (!(c)) { fprintf(stderr, "abi_test: FAIL: %s\n", what); bad = 1; } } while (0)
typedef struct { unsigned char *b; size_t n; } bs;
typedef struct { bs type, data, id; } ev;
typedef struct { bs input; ev *evs; size_t nev; bs lastid; int has_retry; unsigned long long retry; } row;
static int hv(int c) { return c >= '0' && c <= '9' ? c - '0' : c >= 'a' && c <= 'f' ? c - 'a' + 10 : -1; }
static const char *hex(const char *p, bs *o) {   /* p at the first hex digit: read to the closing quote */
  const char *q = strchr(p, '"'); size_t n = (size_t)(q - p) / 2; o->b = malloc(n ? n : 1); o->n = n;
  for (size_t i = 0; i < n; i++) o->b[i] = (unsigned char)(hv(p[2 * i]) * 16 + hv(p[2 * i + 1]));
  return q + 1;
}
static void parse_row(const char *l, row *r) {
  const char *p = strstr(l, "\"input\":\""); p = hex(p + 9, &r->input);
  p = strstr(p, "\"events\":[") + 10; size_t cap = 4; r->evs = malloc(cap * sizeof(ev)); r->nev = 0;
  while (*p == '{') {
    if (r->nev == cap) { cap *= 2; r->evs = realloc(r->evs, cap * sizeof(ev)); }
    ev *e = &r->evs[r->nev++];
    p = hex(strstr(p, "\"type\":\"") + 8, &e->type); p = hex(strstr(p, "\"data\":\"") + 8, &e->data); p = hex(strstr(p, "\"last_event_id\":\"") + 17, &e->id);
    p += 1; if (*p == ',') p++;   /* the closing brace, the comma */
  }
  p = hex(strstr(p, "\"last_event_id\":\"") + 17, &r->lastid);
  p = strstr(p, "\"retry\":") + 8;
  if (*p == 'n') r->has_retry = 0; else { r->has_retry = 1; r->retry = strtoull(p, NULL, 10); }
}
static unsigned long long word(const unsigned char *p) { unsigned long long w = 0; for (int i = 7; i >= 0; i--) w = w << 8 | p[i]; return w; }
/* run the chunks, collect; return 0 if equal to the row */
static int run(const row *r, const unsigned char *const *chunks, const size_t *lens, size_t nchunks, const char **why) {
  vbm_sse *rd; if (vbm_sse_new(&rd) != VBM_SSE_OK) { *why = "new"; return 1; }
  size_t got = 0; int rc = 0; vbm_sse_report rep = {0, 0};
  for (size_t c = 0; c < nchunks && !rc; c++) {
    if (vbm_sse_feed(rd, chunks[c], lens[c], &rep) != VBM_SSE_OK) { *why = "feed"; rc = 1; break; }
    const unsigned char *p = rep.bytes; size_t n = rep.nbytes;
    if (n < 32) { *why = "short report"; rc = 1; break; }
    unsigned long long count = word(p), rset = word(p + 8), rv = word(p + 16), idl = word(p + 24);
    p += 32; n -= 32; if (idl > n) { *why = "id length"; rc = 1; break; }
    const unsigned char *id = p; p += idl; n -= idl;
    if (c == nchunks - 1) {   /* the final state is what the last report says */
      if ((int)rset != r->has_retry || (rset && rv != r->retry) || (!rset && rv != 0)) { *why = "retry"; rc = 1; break; }
      if (idl != r->lastid.n || memcmp(id, r->lastid.b, idl)) { *why = "last event id"; rc = 1; break; }
    }
    for (unsigned long long k = 0; k < count; k++) {
      if (n < 24) { *why = "event header"; rc = 1; break; }
      unsigned long long tl = word(p), dl = word(p + 8), il = word(p + 16); p += 24; n -= 24;
      if (tl > n || dl > n - tl || il > n - tl - dl) { *why = "event lengths"; rc = 1; break; }
      if (got >= r->nev) { *why = "more events than the row"; rc = 1; break; }
      const ev *e = &r->evs[got++];
      if (tl != e->type.n || dl != e->data.n || il != e->id.n || memcmp(p, e->type.b, tl) || memcmp(p + tl, e->data.b, dl) || memcmp(p + tl + dl, e->id.b, il)) { *why = "event"; rc = 1; break; }
      p += tl + dl + il; n -= tl + dl + il;
    }
    if (!rc && n != 0) { *why = "trailing bytes in the report"; rc = 1; }
  }
  if (!rc && got != r->nev) { *why = "fewer events than the row"; rc = 1; }
  vbm_sse_free(rd);
  return rc;
}
int main(int argc, char **argv) {
  if (argc != 2) { fprintf(stderr, "usage: abi_test VECTORS.jsonl\n"); return 2; }
  /* arguments */
  { vbm_sse *r = (vbm_sse *)1; vbm_sse_report rep; unsigned char b[1] = {0};
    CHECK(vbm_sse_new(NULL) == VBM_SSE_ARG, "new(NULL)");
    CHECK(vbm_sse_new(&r) == VBM_SSE_OK && r, "new");
    CHECK(vbm_sse_feed(NULL, b, 1, &rep) == VBM_SSE_ARG && !rep.bytes && !rep.nbytes, "feed(NULL reader)");
    CHECK(vbm_sse_feed(r, b, 1, NULL) == VBM_SSE_ARG, "feed(NULL report)");
    CHECK(vbm_sse_feed(r, NULL, 1, &rep) == VBM_SSE_ARG && !rep.bytes, "feed(NULL, 1)");
    CHECK(vbm_sse_feed(r, NULL, 0, &rep) == VBM_SSE_OK && rep.nbytes == 32, "feed(NULL, 0) is an empty chunk");
    CHECK(vbm_sse_feed(r, b, (size_t)-1, &rep) == VBM_SSE_ARG, "feed(too large)");
    CHECK(vbm_sse_feed(r, b, (size_t)-1 >> 1, &rep) == VBM_SSE_ARG && !rep.bytes, "feed(LEAN_MAX_SMALL_NAT bytes: the limit itself is refused)");
    vbm_sse_free(r); vbm_sse_free(NULL); }
  FILE *f = fopen(argv[1], "r"); if (!f) { perror(argv[1]); return 2; }
  char *line = NULL; size_t cap = 0; ssize_t got; size_t rows = 0, runs = 0;
  while ((got = getline(&line, &cap, f)) > 0) {
    row r; parse_row(line, &r); rows++;
    size_t n = r.input.n; const char *why = "";
    const unsigned char *ch[2]; size_t ln[2];
    ch[0] = r.input.b; ln[0] = n;
    if (run(&r, ch, ln, 1, &why)) { fprintf(stderr, "abi_test: row %zu, whole: %s\n", rows, why); bad = 1; }
    for (size_t k = 0; k <= n; k++) {
      ch[0] = r.input.b; ln[0] = k; ch[1] = r.input.b + k; ln[1] = n - k;
      if (run(&r, ch, ln, 2, &why)) { fprintf(stderr, "abi_test: row %zu, split at %zu: %s\n", rows, k, why); bad = 1; }
      runs++;
    }
    { const unsigned char **cs = malloc((n ? n : 1) * sizeof *cs); size_t *ls = malloc((n ? n : 1) * sizeof *ls);
      for (size_t i = 0; i < n; i++) { cs[i] = r.input.b + i; ls[i] = 1; }
      if (n && run(&r, cs, ls, n, &why)) { fprintf(stderr, "abi_test: row %zu, byte by byte: %s\n", rows, why); bad = 1; }
      free(cs); free(ls); }
    free(r.input.b); free(r.lastid.b);
    for (size_t i = 0; i < r.nev; i++) { free(r.evs[i].type.b); free(r.evs[i].data.b); free(r.evs[i].id.b); }
    free(r.evs);
  }
  free(line); fclose(f);
  CHECK(rows > 100, "the vectors have fewer than 100 rows");
  /* the leak hook: many streams through the library leave the runtime heap where it was */
  { const unsigned char s[] = "retry: 7\nid: 9\nevent: e\ndata: x\ndata: y\n\n: c\r\ndata";
    vbm_sse *r; vbm_sse_report rep; size_t base = 0;
    for (int i = 0; i < 3; i++) { vbm_sse_new(&r); vbm_sse_feed(r, s, sizeof s - 1, &rep); vbm_sse_feed(r, s, 5, &rep); vbm_sse_free(r); }
    base = vbm_sse_rt_live();
    for (int i = 0; i < 2000; i++) { vbm_sse_new(&r); vbm_sse_feed(r, s, sizeof s - 1, &rep); vbm_sse_feed(r, s, 5, &rep); vbm_sse_free(r); }
    CHECK(vbm_sse_rt_live() == base, "the runtime heap grows over 2000 streams: a leak");
    CHECK(base > 0, "the leak hook reads zero (it is not wired)"); }
  if (bad) return 1;
  printf("abi_test: %zu rows, %zu two-way splits and every whole and byte-at-a-time cut agree with the reference; arguments checked; runtime heap flat over 2000 streams\n", rows, runs);
  return 0;
}
